package com.coraline.feast;
import net.minecraft.nbt.*;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.GameTestHolder;
import java.util.*;
@GameTestHolder("coraline")
@net.minecraftforge.gametest.PrefixGameTestTemplate(false)
public final class MotherAwayLedgerGameTests {
    private static final UUID OWNER=new UUID(0,1),WITNESS=new UUID(0,2);
    private static CompoundTag prepared(long seed){var n=new CompoundTag();MotherAwayLedger.prepare(n,OWNER,7,seed);return n;}
    private static CompoundTag absent(long seed){var n=prepared(seed);MotherAwayLedger.departed(n);return n;}
    private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    private static void returning(CompoundTag n){n.putInt("Remaining",1);MotherAwayLedger.tick(n,false);while(n.getString("Stage").equals("RETURN_DELAY"))MotherAwayLedger.tick(n,false);}
    @GameTest(template="empty") public static void timerStartsOnlyAfterDeparture(GameTestHelper h){var n=prepared(1);for(int i=0;i<500;i++)MotherAwayLedger.tick(n,false);check(!n.contains("Duration")&&!n.contains("Remaining"),"walking is not absence time");MotherAwayLedger.departed(n);check(n.getInt("Remaining")==n.getInt("Duration"),"starts at full chosen duration");h.succeed();}
    @GameTest(template="empty") public static void durationsStayInAuthoredRange(GameTestHelper h){var values=new HashSet<Integer>();for(int seed=0;seed<20000;seed++){var n=absent(seed);int duration=n.getInt("Duration");check(duration>=12000&&duration<=42000,"10–35 active minutes");values.add(duration);}check(values.size()>10000,"not a fixed timer");h.succeed();}
    @GameTest(template="empty") public static void departureIsIdempotentAcrossSave(GameTestHelper h){var n=absent(42);for(int i=0;i<100;i++)MotherAwayLedger.tick(n,false);var saved=n.copy();int left=saved.getInt("Remaining");MotherAwayLedger.departed(saved);check(saved.getInt("Remaining")==left&&saved.getInt("Duration")==n.getInt("Duration"),"reconnect cannot reroll/reset");h.succeed();}
    @GameTest(template="empty") public static void pausedOwnerTimeDoesNotAdvance(GameTestHelper h){var n=absent(3);var before=n.copy();for(int i=0;i<2000;i++)MotherAwayLedger.tick(n,true);check(n.equals(before),"offline/confrontation time paused");MotherAwayLedger.tick(n,false);check(n.getInt("Remaining")==before.getInt("Remaining")-1,"one active tick");h.succeed();}
    @GameTest(template="empty") public static void normalExpiryReturnsOnlyOnce(GameTestHelper h){var n=absent(8);n.putInt("Remaining",1);MotherAwayLedger.tick(n,false);check(n.getString("Stage").equals("RETURN_DELAY")&&!n.getBoolean("Early"),"normal return");int travel=n.getInt("TravelRemaining");check(travel>=300&&travel<=800,"15–40 seconds travel");for(int i=0;i<travel+100;i++)MotherAwayLedger.tick(n,false);check(n.getString("Stage").equals("RETURNING")&&n.getInt("ReturnCount")==1,"one return only");h.succeed();}
    @GameTest(template="empty") public static void legitimateReportSupersedesAbsence(GameTestHelper h){var n=absent(9);int remaining=n.getInt("Remaining");check(MotherAwayLedger.report(n,WITNESS,"doll","forbidden",10,"",100),"valid report");check(n.getBoolean("Early")&&n.getString("Stage").equals("RETURN_DELAY")&&n.getInt("Remaining")==remaining,"immediate return transition, no invented elapsed time");h.succeed();}
    @GameTest(template="empty") public static void repeatedReportDoesNotResetReturn(GameTestHelper h){var n=absent(10);MotherAwayLedger.report(n,WITNESS,"rat","drawer",10,"",100);MotherAwayLedger.tick(n,false);int left=n.getInt("TravelRemaining");MotherAwayLedger.report(n,WITNESS,"rat","drawer",10,"",100);MotherAwayLedger.report(n,new UUID(0,3),"doll","forbidden",11,"",101);check(n.getInt("TravelRemaining")==left&&n.getInt("ReturnCount")==1,"reports do not restart travel");check(n.getList("Reports",Tag.TAG_COMPOUND).size()==2,"same witness/time deduplicated");h.succeed();}
    @GameTest(template="empty") public static void reportJournalContainsOnlyGivenObservation(GameTestHelper h){var n=absent(11);MotherAwayLedger.report(n,WITNESS,"doll","forbidden",500,"blind_spots",200);var report=n.getList("Reports",Tag.TAG_COMPOUND).getCompound(0);check(report.getString("Identified").equals("blind_spots")&&report.getLong("Position")==500,"exact observed identity/location");check(!report.contains("Inventory")&&!report.contains("Journal")&&!report.contains("Secrets"),"no invented inventory/journal knowledge");h.succeed();}
    @GameTest(template="empty") public static void invalidAndPrematureReportsRejected(GameTestHelper h){var n=prepared(12);check(!MotherAwayLedger.report(n,WITNESS,"rat","drawer",1,"",1),"departure cannot receive absent report");MotherAwayLedger.departed(n);check(!MotherAwayLedger.report(n,null,"doll","forbidden",1,"",1),"missing witness");check(!MotherAwayLedger.report(n,WITNESS,"client","forbidden",1,"",1),"unknown channel");check(!MotherAwayLedger.report(n,WITNESS,"doll","",1,"",1),"ordinary activity is not a report");check(n.getList("Reports",Tag.TAG_COMPOUND).isEmpty()&&!n.getBoolean("Early"),"rejected input inert");h.succeed();}
    @GameTest(template="empty") public static void observationsRemainBounded(GameTestHelper h){var n=absent(13);for(int i=0;i<1000;i++)MotherAwayLedger.report(n,WITNESS,"doll","location",i,"",i);check(n.getList("Reports",Tag.TAG_COMPOUND).size()==32&&n.getLong("LastReportedPosition")==999,"bounded latest observations");h.succeed();}
    @GameTest(template="empty") public static void safeUnseenHomeReturnHasNoAccusation(GameTestHelper h){var n=absent(14);returning(n);MotherAwayLedger.home(n,true);check(MotherAwayLedger.safeReturn(n)&&!n.getBoolean("ActionableReport")&&n.getList("Reports",Tag.TAG_COMPOUND).isEmpty(),"stealth success remains unknown");h.succeed();}
    @GameTest(template="empty") public static void locationReportDoesNotInventTheft(GameTestHelper h){var n=absent(15);MotherAwayLedger.report(n,WITNESS,"rat","location",44,"",20);while(n.getString("Stage").equals("RETURN_DELAY"))MotherAwayLedger.tick(n,false);MotherAwayLedger.home(n,true);check(MotherAwayLedger.safeReturn(n)&&!n.getBoolean("ActionableReport"),"known location alone does not mean theft");h.succeed();}
    @GameTest(template="empty") public static void forbiddenReportSurvivesPlayerReturn(GameTestHelper h){var n=absent(16);MotherAwayLedger.report(n,WITNESS,"doll","forbidden",44,"",20);while(n.getString("Stage").equals("RETURN_DELAY"))MotherAwayLedger.tick(n,false);MotherAwayLedger.home(n,true);check(!MotherAwayLedger.safeReturn(n)&&n.getBoolean("ActionableReport"),"home boundary is not immunity");h.succeed();}
    @GameTest(template="empty") public static void IdentifiedEvidenceIsActionable(GameTestHelper h){var n=absent(17);MotherAwayLedger.report(n,WITNESS,"rat","location",44,"personal_keyring",20);check(n.getBoolean("ActionableReport"),"identified restricted evidence matters independently of room");h.succeed();}
    @GameTest(template="empty") public static void missingOwnerRequiresExistingSearch(GameTestHelper h){var n=absent(18);returning(n);MotherAwayLedger.home(n,false);check(!MotherAwayLedger.safeReturn(n),"not home");MotherAwayLedger.searching(n);MotherAwayLedger.home(n,true);check(n.getString("Stage").equals("SEARCHING")&&n.getBoolean("SearchBegun"),"crossing boundary cannot cancel search");h.succeed();}
    @GameTest(template="empty") public static void completionIsTerminal(GameTestHelper h){var n=absent(19);MotherAwayLedger.completed(n);var before=n.copy();MotherAwayLedger.tick(n,false);MotherAwayLedger.departed(n);MotherAwayLedger.searching(n);check(!MotherAwayLedger.report(n,WITNESS,"rat","drawer",1,"",1),"completed report rejected");check(n.equals(before)&&!MotherAwayLedger.safeReturn(n),"no restart or reward after cleanup");h.succeed();}
    @GameTest(template="empty") public static void ownershipRequiresMatchingLiveInstance(GameTestHelper h){var n=prepared(20);check(MotherAwayLedger.owned(n,OWNER,7),"current owner/serial");check(!MotherAwayLedger.owned(n,WITNESS,7)&&!MotherAwayLedger.owned(n,OWNER,8)&&!MotherAwayLedger.owned(n,null,7),"foreign/stale/null owner rejected");MotherAwayLedger.completed(n);check(!MotherAwayLedger.owned(n,OWNER,7),"terminal lease rejected");h.succeed();}

}
